function rp_write($path,array $entities,$version=null){$f=new DomainBackupFormat();$version=null===$version?DomainBackupFormat::VERSION:absint($version);$config=array('certverify_fields'=>array('exists'=>true,'value'=>array()),'certverify_retired_fields'=>array('exists'=>true,'value'=>array()),'certverify_settings'=>array('exists'=>true,'value'=>array()));$types=DomainBackupFormat::entity_types_for_version($version);$counts=array_fill_keys($types,0);$max=array_fill_keys($types,0);foreach($entities as $e){if(!isset($counts[$e['entity']]))continue;$counts[$e['entity']]++;$max[$e['entity']]=max($max[$e['entity']],(int)$e['data']['id']);}$bounds=array();foreach($counts as $k=>$n)$bounds[$k]=array('count'=>$n,'max_id'=>$max[$k]);$manifest=array('type'=>'manifest','format'=>DomainBackupFormat::FORMAT,'format_version'=>$version,'plugin_version'=>'1.6.3','generated_at'=>'2026-08-22T00:00:00Z','generation'=>'g1','entities'=>$bounds,'configuration'=>$config,'configuration_hash'=>hash('sha256',wp_json_encode($config,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)));$lines=array();$line=$f->encode_line($manifest);$lines[]=$line;$hash=$f->next_hash('',$line,$version);foreach($entities as $e){if(!in_array($e['entity'],$types,true))continue;$line=$f->encode_line(array('type'=>'entity')+$e);$lines[]=$line;$hash=$f->next_hash($hash,$line,$version);} $lines[]=$f->encode_line(array('type'=>'integrity','records'=>array_sum($counts),'chain_sha256'=>$hash));file_put_contents($path,implode('',$lines));}
