);
$valid=$root.'/valid.data';rp_write($valid,$entities);$r=(new DomainRestorePreflightService())->analyze($valid);rp_same(false,is_wp_error($r),'valid');rp_same(true,$r['ready'],'ready');rp_same(7,$r['records'],'records');echo "PASS  valid complete-domain backup passes semantic relationship preflight\n";
$broken=$entities;$broken[6]['data']['series_id']=999;$bad=$root.'/bad.data';rp_write($bad,$broken);$r=(new DomainRestorePreflightService())->analyze($bad);rp_same('certloom_domain_restore_semantic_invalid',$r->get_error_code(),'bad event relation');$details=$r->get_error_data();rp_same('event_series_missing',$details[0]['code'],'relation code');echo "PASS  restore preflight rejects broken cross-entity relationships after file integrity passes\n";
$wrong=$entities;$wrong[5]['data']['display_number']='OTHER';$bad2=$root.'/bad-number.data';rp_write($bad2,$wrong);$r=(new DomainRestorePreflightService())->analyze($bad2);rp_same('certloom_domain_restore_semantic_invalid',$r->get_error_code(),'number assignment mismatch');echo "PASS  restore preflight rejects Version numbers not assigned to their Credential Series\n";
$badprev=$entities;$badprev[5]['data']['previous_version_id']=999;$bad3=$root.'/bad-previous.data';rp_write($bad3,$badprev);$r=(new DomainRestorePreflightService())->analyze($bad3);rp_same('certloom_domain_restore_semantic_invalid',$r->get_error_code(),'previous version mismatch');$details=$r->get_error_data();$codes=array_column($details,'code');if(!in_array('previous_version_invalid',$codes,true))throw new RuntimeException('Expected previous_version_invalid');echo "PASS  restore preflight rejects missing or cross-Series previous-Version lineage\n";
